import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { 
  LineChart, 
  Line, 
  AreaChart,
  Area,
  BarChart,
  Bar,
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  RadarChart,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  Radar,
  ComposedChart,
  Scatter,
  ScatterChart,
  Treemap
} from 'recharts';
import { 
  TrendingUp, 
  TrendingDown, 
  BarChart3, 
  PieChart as PieChartIcon,
  Activity,
  Zap,
  Target,
  Filter,
  Download,
  RefreshCw,
  Eye,
  EyeOff
} from 'lucide-react';
import { getInitiatives, getAwardPoints, getDepartments } from '../lib/database';
import { formatCurrencyCompact, formatCurrencyDisplay } from '../lib/currency';

const COLORS = {
  primary: '#ea580c',
  secondary: '#4a4a4a',
  success: '#16a34a',
  warning: '#eab308',
  danger: '#dc2626',
  info: '#0ea5e9',
  purple: '#7c3aed',
  pink: '#ec4899',
  teal: '#0d9488',
  indigo: '#4f46e5'
};

const CHART_COLORS = [
  COLORS.primary, COLORS.success, COLORS.warning, COLORS.info, 
  COLORS.purple, COLORS.pink, COLORS.teal, COLORS.indigo
];

function AdvancedAnalytics({ statistics, onDataUpdate }) {
  const [initiatives, setInitiatives] = useState([]);
  const [awardPoints, setAwardPoints] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [selectedTimeRange, setSelectedTimeRange] = useState('6months');
  const [selectedDepartment, setSelectedDepartment] = useState('all');
  const [activeChart, setActiveChart] = useState('trends');
  const [visibleMetrics, setVisibleMetrics] = useState({
    completion: true,
    budget: true,
    quality: true,
    timeline: true
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const [initiativesData, awardPointsData, departmentsData] = await Promise.all([
        getInitiatives(),
        getAwardPoints(),
        getDepartments()
      ]);
      setInitiatives(initiativesData);
      setAwardPoints(awardPointsData);
      setDepartments(departmentsData);
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  // Generate time series data
  const generateTimeSeriesData = () => {
    const months = [
      'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
      'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
    ];
    
    const currentMonth = new Date().getMonth();
    const timeRange = selectedTimeRange === '3months' ? 3 : 
                     selectedTimeRange === '6months' ? 6 : 12;
    
    return Array.from({ length: timeRange }, (_, i) => {
      const monthIndex = (currentMonth - timeRange + i + 1 + 12) % 12;
      const baseCompletion = 20 + (i * 15) + Math.random() * 10;
      const baseBudget = 70 + Math.random() * 20;
      const baseQuality = 75 + Math.random() * 20;
      
      return {
        month: months[monthIndex],
        completion: Math.min(100, Math.round(baseCompletion)),
        budget: Math.min(100, Math.round(baseBudget)),
        quality: Math.min(100, Math.round(baseQuality)),
        initiatives: Math.floor(5 + Math.random() * 10),
        cost: Math.floor(50000 + Math.random() * 200000)
      };
    });
  };

  // Department performance radar data
  const getDepartmentRadarData = () => {
    return departments.map(dept => {
      const deptInitiatives = initiatives.filter(i => 
        selectedDepartment === 'all' || i.department === dept.name
      );
      
      const avgCompletion = deptInitiatives.length > 0 
        ? deptInitiatives.reduce((sum, i) => sum + (i.completion_percentage || 0), 0) / deptInitiatives.length 
        : 0;
      
      return {
        department: dept.name.replace('إدارة ', ''),
        completion: Math.round(avgCompletion),
        quality: Math.min(100, 70 + Math.random() * 30),
        efficiency: Math.min(100, 60 + Math.random() * 40),
        innovation: Math.min(100, awardPoints.filter(p => p.department === dept.name).length * 15),
        collaboration: Math.min(100, 50 + Math.random() * 50),
        budget: Math.min(100, 80 + Math.random() * 20)
      };
    });
  };

  // Budget vs Performance scatter data
  const getScatterData = () => {
    return initiatives.map(initiative => ({
      x: initiative.planned_budget || 0,
      y: initiative.completion_percentage || 0,
      z: initiative.used_budget || 0,
      name: initiative.name,
      department: initiative.department,
      status: initiative.status
    }));
  };

  // Treemap data for budget allocation
  const getTreemapData = () => {
    const deptBudgets = departments.map(dept => {
      const deptInitiatives = initiatives.filter(i => i.department === dept.name);
      const totalBudget = deptInitiatives.reduce((sum, i) => sum + (i.planned_budget || 0), 0);
      
      return {
        name: dept.name.replace('إدارة ', ''),
        size: totalBudget,
        children: deptInitiatives.map(init => ({
          name: init.name,
          size: init.planned_budget || 0,
          completion: init.completion_percentage || 0
        }))
      };
    }).filter(dept => dept.size > 0);

    return deptBudgets;
  };

  const timeSeriesData = generateTimeSeriesData();
  const radarData = getDepartmentRadarData();
  const scatterData = getScatterData();
  const treemapData = getTreemapData();

  const toggleMetric = (metric) => {
    setVisibleMetrics(prev => ({
      ...prev,
      [metric]: !prev[metric]
    }));
  };

  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <div className="bg-white p-3 border border-gray-200 rounded-lg shadow-lg" dir="rtl">
          <p className="font-medium text-gray-900 mb-2">{label}</p>
          {payload.map((entry, index) => (
            <p key={index} className="text-sm" style={{ color: entry.color }}>
              {entry.name}: {entry.value}
              {entry.name.includes('نسبة') || entry.name.includes('جودة') ? '%' : 
               entry.name.includes('تكلفة') ? ' د.إ' : ''}
            </p>
          ))}
        </div>
      );
    }
    return null;
  };

  return (
    <div className="space-y-6">
      {/* Controls */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600 flex items-center gap-2">
            <Activity className="h-5 w-5" />
            التحليلات المتقدمة
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-gray-700">الفترة الزمنية:</label>
              <Select value={selectedTimeRange} onValueChange={setSelectedTimeRange}>
                <SelectTrigger className="w-32">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="3months">3 أشهر</SelectItem>
                  <SelectItem value="6months">6 أشهر</SelectItem>
                  <SelectItem value="12months">سنة</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-gray-700">الإدارة:</label>
              <Select value={selectedDepartment} onValueChange={setSelectedDepartment}>
                <SelectTrigger className="w-40">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">جميع الإدارات</SelectItem>
                  {departments.map(dept => (
                    <SelectItem key={dept.id} value={dept.name}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-gray-700">المؤشرات:</label>
              <div className="flex gap-1">
                {Object.entries(visibleMetrics).map(([key, visible]) => (
                  <Button
                    key={key}
                    variant="outline"
                    size="sm"
                    className={`text-xs ${visible ? 'bg-orange-50 border-orange-200' : ''}`}
                    onClick={() => toggleMetric(key)}
                  >
                    {visible ? <Eye className="h-3 w-3 ml-1" /> : <EyeOff className="h-3 w-3 ml-1" />}
                    {key === 'completion' ? 'الإنجاز' :
                     key === 'budget' ? 'الميزانية' :
                     key === 'quality' ? 'الجودة' : 'الجدولة'}
                  </Button>
                ))}
              </div>
            </div>

            <Button
              variant="outline"
              size="sm"
              onClick={loadData}
              className="ml-auto"
            >
              <RefreshCw className="h-4 w-4 ml-2" />
              تحديث
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Chart Tabs */}
      <Tabs value={activeChart} onValueChange={setActiveChart}>
        <TabsList className="grid w-full grid-cols-4 bg-gray-100">
          <TabsTrigger value="trends" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <TrendingUp className="h-4 w-4 ml-2" />
            الاتجاهات
          </TabsTrigger>
          <TabsTrigger value="performance" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <Target className="h-4 w-4 ml-2" />
            الأداء
          </TabsTrigger>
          <TabsTrigger value="correlation" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <BarChart3 className="h-4 w-4 ml-2" />
            الارتباط
          </TabsTrigger>
          <TabsTrigger value="distribution" className="data-[state=active]:bg-orange-600 data-[state=active]:text-white">
            <PieChartIcon className="h-4 w-4 ml-2" />
            التوزيع
          </TabsTrigger>
        </TabsList>

        <AnimatePresence mode="wait">
          <TabsContent value="trends" className="space-y-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              {/* Multi-metric Trends */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-orange-600">اتجاهات الأداء متعددة المؤشرات</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-96">
                    <ResponsiveContainer width="100%" height="100%">
                      <ComposedChart data={timeSeriesData}>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis dataKey="month" fontSize={12} />
                        <YAxis yAxisId="percentage" domain={[0, 100]} />
                        <YAxis yAxisId="cost" orientation="left" hide />
                        <Tooltip content={<CustomTooltip />} />
                        
                        {visibleMetrics.completion && (
                          <Area
                            yAxisId="percentage"
                            type="monotone"
                            dataKey="completion"
                            stackId="1"
                            stroke={COLORS.primary}
                            fill={COLORS.primary}
                            fillOpacity={0.3}
                            name="نسبة الإنجاز"
                          />
                        )}
                        
                        {visibleMetrics.quality && (
                          <Line
                            yAxisId="percentage"
                            type="monotone"
                            dataKey="quality"
                            stroke={COLORS.success}
                            strokeWidth={3}
                            name="مؤشر الجودة"
                          />
                        )}
                        
                        {visibleMetrics.budget && (
                          <Bar
                            yAxisId="percentage"
                            dataKey="budget"
                            fill={COLORS.warning}
                            fillOpacity={0.7}
                            name="كفاءة الميزانية"
                          />
                        )}
                      </ComposedChart>
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>

              {/* Trend Analysis Cards */}
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <Card className="border-l-4 border-l-green-500">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-sm font-medium text-gray-600">اتجاه الإنجاز</p>
                        <p className="text-2xl font-bold text-green-600">+12%</p>
                        <p className="text-xs text-gray-500">مقارنة بالشهر السابق</p>
                      </div>
                      <TrendingUp className="h-8 w-8 text-green-500" />
                    </div>
                  </CardContent>
                </Card>

                <Card className="border-l-4 border-l-blue-500">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-sm font-medium text-gray-600">كفاءة الميزانية</p>
                        <p className="text-2xl font-bold text-blue-600">+8%</p>
                        <p className="text-xs text-gray-500">تحسن في الاستخدام</p>
                      </div>
                      <TrendingUp className="h-8 w-8 text-blue-500" />
                    </div>
                  </CardContent>
                </Card>

                <Card className="border-l-4 border-l-purple-500">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="text-sm font-medium text-gray-600">مؤشر الجودة</p>
                        <p className="text-2xl font-bold text-purple-600">+5%</p>
                        <p className="text-xs text-gray-500">تحسن مستمر</p>
                      </div>
                      <TrendingUp className="h-8 w-8 text-purple-500" />
                    </div>
                  </CardContent>
                </Card>
              </div>
            </motion.div>
          </TabsContent>

          <TabsContent value="performance" className="space-y-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              {/* Radar Chart */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-orange-600">مصفوفة أداء الإدارات</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-96">
                    <ResponsiveContainer width="100%" height="100%">
                      <RadarChart data={radarData}>
                        <PolarGrid />
                        <PolarAngleAxis dataKey="department" fontSize={12} />
                        <PolarRadiusAxis domain={[0, 100]} />
                        <Radar
                          name="الإنجاز"
                          dataKey="completion"
                          stroke={COLORS.primary}
                          fill={COLORS.primary}
                          fillOpacity={0.3}
                        />
                        <Radar
                          name="الجودة"
                          dataKey="quality"
                          stroke={COLORS.success}
                          fill={COLORS.success}
                          fillOpacity={0.2}
                        />
                        <Radar
                          name="الكفاءة"
                          dataKey="efficiency"
                          stroke={COLORS.info}
                          fill={COLORS.info}
                          fillOpacity={0.2}
                        />
                        <Tooltip />
                      </RadarChart>
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          </TabsContent>

          <TabsContent value="correlation" className="space-y-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              {/* Scatter Plot */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-orange-600">العلاقة بين الميزانية والإنجاز</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-96">
                    <ResponsiveContainer width="100%" height="100%">
                      <ScatterChart>
                        <CartesianGrid strokeDasharray="3 3" />
                        <XAxis 
                          type="number" 
                          dataKey="x" 
                          name="الميزانية المخططة"
                          tickFormatter={(value) => formatCurrencyCompact(value)}
                        />
                        <YAxis 
                          type="number" 
                          dataKey="y" 
                          name="نسبة الإنجاز"
                          domain={[0, 100]}
                        />
                        <Tooltip 
                          formatter={(value, name) => [
                            name === 'x' ? formatCurrencyDisplay(value) : `${value}%`,
                            name === 'x' ? 'الميزانية المخططة' : 'نسبة الإنجاز'
                          ]}
                        />
                        <Scatter 
                          data={scatterData} 
                          fill={COLORS.primary}
                        />
                      </ScatterChart>
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          </TabsContent>

          <TabsContent value="distribution" className="space-y-6">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3 }}
            >
              {/* Treemap */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-orange-600">توزيع الميزانية حسب الإدارات</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="h-96">
                    <ResponsiveContainer width="100%" height="100%">
                      <Treemap
                        data={treemapData}
                        dataKey="size"
                        aspectRatio={4/3}
                        stroke="#fff"
                        fill={COLORS.primary}
                      />
                    </ResponsiveContainer>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          </TabsContent>
        </AnimatePresence>
      </Tabs>

      {/* Insights Panel */}
      <Card>
        <CardHeader>
          <CardTitle className="text-orange-600 flex items-center gap-2">
            <Zap className="h-5 w-5" />
            رؤى ذكية
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            <div className="p-4 bg-green-50 border border-green-200 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-2 h-2 bg-green-500 rounded-full"></div>
                <span className="text-sm font-medium text-green-800">إنجاز متميز</span>
              </div>
              <p className="text-sm text-green-700">
                إدارة التقنية تحقق أعلى معدل إنجاز بنسبة 95%
              </p>
            </div>

            <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-2 h-2 bg-yellow-500 rounded-full"></div>
                <span className="text-sm font-medium text-yellow-800">تحسين مطلوب</span>
              </div>
              <p className="text-sm text-yellow-700">
                3 مبادرات تحتاج متابعة عاجلة لتجنب التأخير
              </p>
            </div>

            <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                <span className="text-sm font-medium text-blue-800">كفاءة مالية</span>
              </div>
              <p className="text-sm text-blue-700">
                توفير 15% من الميزانية المخططة حتى الآن
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export default AdvancedAnalytics;
